// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Olasılık hesapları ve koşullu olasılık (orta).
const ozStatistics7Orta = <(String, String, List<String>, String)>[
  ('Hileli bir zarda her çift sayının gelme olasılığı her tek sayınınkinin iki katıdır; tek sayılar kendi aralarında, çift sayılar da kendi aralarında eşit olasılıklıdır. Bu zarda 1 gelme olasılığı kaçtır?', '1/9', ['1/6', '2/9', '1/12'], 'Tek yüzlere p, çift yüzlere 2p denirse 3p + 6p = 1 olur ve p = 1/9 bulunur.'),
  ('Bir zarda 6 gelme olasılığı 1/3\'tür; diğer beş yüz birbiriyle eşit olasılıklıdır. Bu zarla tek sayı gelme olasılığı kaçtır?', '2/5', ['7/15', '1/3', '3/5'], 'Kalan 2/3 beş yüze eşit paylaşılır, her biri 2/15 olur. 1, 3 ve 5 için toplam 6/15 = 2/5\'tir.'),
  ('Bir zarda her yüzün gelme olasılığı üzerindeki sayının karesiyle orantılıdır. Bu zarla 5 ya da 6 gelme olasılığı kaçtır?', '61/91', ['25/91', '36/91', '55/91'], 'Kareler toplamı 1 + 4 + 9 + 16 + 25 + 36 = 91\'dir. 5 ve 6 için (25 + 36)/91 = 61/91 bulunur.'),
  ('Bir zarda 1, 2 ve 3 yüzlerinin her birinin gelme olasılığı a, 4, 5 ve 6 yüzlerinin her birininki 2a\'dır. Zar iki kez atılırsa toplamın 12 olma olasılığı kaçtır?', '4/81', ['16/81', '2/9', '1/81'], '3a + 6a = 1\'den a = 1/9, P(6) = 2/9 bulunur. Toplam 12 için iki atışta da 6 gerekir: (2/9)² = 4/81.'),
  ('Yazı gelme olasılığı p olan bir para iki kez atılıyor. En az bir yazı gelme olasılığı 0,64 olduğuna göre p kaçtır?', '0,4', ['0,6', '0,36', '0,8'], 'Hiç yazı gelmeme olasılığı (1 − p)² = 0,36\'dır; buradan 1 − p = 0,6 ve p = 0,4 bulunur.'),
  ('İki olay için P(A ∪ B) = 0,9, P(A\') = 0,4 ve P(B\') = 0,3 veriliyor. P(A ∩ B) kaçtır?', '0,4', ['0,3', '0,2', '0,24'], 'P(A) = 0,6 ve P(B) = 0,7\'dir. Toplama kuralından 0,9 = 0,6 + 0,7 − P(A ∩ B), yani P(A ∩ B) = 0,4 bulunur.'),
  ('P(A) = 0,35 ve P(B) = 0,6 olan iki olay için P(A ∩ B) en büyük değerini hangi durumda alır?', 'A, B\'nin alt kümesi olduğunda', ['A ile B ayrık olduğunda', 'A ile B birbirinden bağımsız olduğunda', 'A ∪ B kesin olay olduğunda'], 'Kesişim küçük olayı aşamaz; en büyük değer olan 0,35\'e A ⊂ B olduğunda ulaşılır.'),
  ('P(A) = 0,4, P(B) = 0,3 ve P(A ∪ B) = 0,55 olarak veriliyor. P(A\' ∪ B\') kaçtır?', '0,85', ['0,45', '0,725', '0,15'], 'P(A ∩ B) = 0,4 + 0,3 − 0,55 = 0,15\'tir. De Morgan\'a göre A\' ∪ B\' = (A ∩ B)\' olduğundan olasılık 1 − 0,15 = 0,85\'tir.'),
  ('Birleşimin olasılığının, olayların olasılıkları toplamından büyük olamayacağını söyleyen eşitsizlik hangisidir?', 'Boole eşitsizliği', ['Çebişev eşitsizliği', 'Jensen eşitsizliği', 'Markov eşitsizliği'], 'P(A₁ ∪ … ∪ Aₙ) ≤ P(A₁) + … + P(Aₙ) bağıntısı Boole eşitsizliği (birleşim sınırı) olarak bilinir.'),
  ('Aynı deneyde P(A) = 0,6 ve P(B) = 0,6 olan iki olay için hangisi kesinlikle doğrudur?', 'Ayrık olamazlar', ['Bağımsızdırlar', 'Birbirinin tümleyenidir', 'Biri ötekinin alt kümesidir'], 'Ayrık olsalardı birleşimin olasılığı 1,2 olurdu; bu imkânsızdır. Dolayısıyla P(A ∩ B) en az 0,2\'dir.'),
  ('A ve B iki olay olmak üzere A ∪ B olayı, ayrık üç parçanın birleşimi olarak nasıl yazılabilir?', 'A∩B\', A∩B ve A\'∩B', ['A, B ve A∩B', 'A\', B\' ve A∩B', 'A∩B\', A\'∩B\' ve A\'∩B'], 'Birleşim; yalnız A, ikisi birden ve yalnız B bölgelerinden oluşur. Bu üç bölge birbiriyle kesişmez.'),
  ('Bir anket grubunda kişilerin %55\'i gazete, %40\'ı dergi okuyor; %10\'u ikisini de okumuyor. Rastgele seçilen birinin ikisini de okuma olasılığı kaçtır?', '0,05', ['0,15', '0,125', '0,25'], 'P(G ∪ D) = 0,9\'dur. 0,9 = 0,55 + 0,40 − P(G ∩ D) eşitliğinden kesişim 0,05 bulunur.'),
  ('P(B) > 0 olmak üzere aşağıdaki toplamlardan hangisi her zaman 1\'e eşittir?', 'P(A|B) + P(A\'|B)', ['P(A|B) + P(A|B\')', 'P(A|B) + P(B|A) − P(A∩B)', 'P(A|B) + P(B\'|A)'], 'B verildiğinde A ile A\' bu kısıtlı uzayı ayrık iki parçaya böler; bu yüzden koşullu olasılıkları toplamı 1\'dir.'),
  ('Bir şirkette 60 kadın ve 40 erkek çalışıyor; kadınların 15\'i, erkeklerin 10\'u yöneticidir. Cinsiyet ile yönetici olma arasındaki ilişki için hangisi doğrudur?', 'Bağımsızdırlar; iki grupta da oran 1/4\'tür', ['Kadınların yönetici olma olasılığı daha yüksektir', 'Erkeklerin yönetici olma olasılığı daha yüksektir', 'Bağımlıdırlar; yöneticilerin çoğu kadındır'], 'P(yönetici) = 25/100 = 1/4; kadınlarda 15/60 = 1/4, erkeklerde 10/40 = 1/4\'tür. Koşullu olasılıklar eşit olduğundan olaylar bağımsızdır.'),
  ('İki zar atılıyor ve zarlardan en az birinin 6 geldiği biliniyor. İki zarın da 6 olma olasılığı kaçtır?', '1/11', ['5/36', '1/36', '1/12'], 'En az bir 6 içeren 11 eşit olası sıralı sonuç vardır; bunlardan yalnız (6, 6) iki zarın da 6 olmasıdır.'),
  ('İki zar atılıyor. Birinci zarın 3 geldiği bilindiğinde toplamın 7 olma olasılığı ile toplamın 7 olma olasılığı karşılaştırılırsa hangisi doğrudur?', 'İkisi de 1/6\'dır; olaylar bağımsızdır', ['Koşullu olasılık 1/3 ile daha büyüktür', 'Koşullu olasılık 1/36 ile daha küçüktür', 'Koşullu olasılık 1, diğeri 1/6\'dır'], 'Birinci zar ne olursa olsun ikinci zarın tam bir değeri toplamı 7 yapar; koşullu olasılık 1/6 kalır ve koşulsuz değerle aynıdır.'),
  ('A ve C ayrık olaylardır. P(B) > 0, P(A|B) = 0,3 ve P(C|B) = 0,25 ise P(A ∪ C | B) kaçtır?', '0,55', ['0,475', '0,075', '0,05'], 'Koşullu olasılık da bir olasılık ölçüsüdür; ayrık olaylar için toplama kuralı geçerlidir: 0,3 + 0,25 = 0,55.'),
  ('52\'lik bir desteden yerine koymadan art arda üç kart çekiliyor. Üç kartın da kupa olma olasılığı kaçtır?', '11/850', ['13/1700', '3/52', '13/850'], 'Çarpma kuralıyla (13/52)(12/51)(11/50) = 1716/132600 = 11/850 bulunur.'),
  ('Olasılıkları ve kesişimleri sıfırdan büyük iki olay için P(A|B) = P(B|A) eşitliği hangi durumda sağlanır?', 'P(A) = P(B) olduğunda', ['A ile B bağımsız olduğunda', 'A ile B ayrık olduğunda', 'P(A ∩ B) = 1/2 olduğunda'], 'P(A ∩ B)/P(B) = P(A ∩ B)/P(A) eşitliği, kesişim sıfırdan büyükken yalnız P(A) = P(B) ise sağlanır.'),
  ('Bir okulda öğrencilerin %25\'i hem satranç hem müzik kulübünde, %40\'ı müzik kulübündedir. Müzik kulübündeki bir öğrencinin satranç kulübünde de olma olasılığı ile satranç oynayan bir öğrencinin müzik kulübünde olma olasılığı için hangisi kesindir?', 'Birincisi 0,625\'tir; ikincisini bulmak için satranççı oranı gerekir', ['İkisi de 0,625\'tir, çünkü kesişim ortaktır ve oranlar simetriktir', 'İkisi de 0,25\'tir', 'Birincisi 0,1\'dir; ikincisi 0,625\'tir'], 'P(S|M) = 0,25/0,40 = 0,625\'tir. P(M|S) için paydada P(S) gerekir ve bu veri verilmemiştir.'),
  ('Bir sınıfta öğrencilerin %60\'ı İngilizceden, %50\'si Almancadan geçmiştir. İngilizceden geçenlerin %70\'i Almancadan da geçmiştir. Almancadan geçen bir öğrencinin İngilizceden de geçmiş olma olasılığı kaçtır?', '0,84', ['0,525', '0,42', '0,60'], 'P(İ ∩ A) = 0,6 × 0,7 = 0,42\'dir. P(İ|A) = 0,42 / 0,5 = 0,84 bulunur.'),
  ('Aşağıdaki olay çiftlerinden hangisi, olaylar ne olursa olsun her zaman bağımsızdır?', 'Herhangi bir olay ile kesin olay', ['Herhangi bir olay ile tümleyeni', 'Ayrık iki olay', 'Biri ötekini kapsayan, olasılığı sıfırdan büyük iki olay'], 'S kesin olay olmak üzere P(A ∩ S) = P(A) = P(A)·1 olduğundan eşitlik her zaman sağlanır.'),
  ('İki olay için P(A) = 0,3, P(B) = 0,4 ve P(A ∪ B) = 0,58 veriliyor. Bu iki olayın ilişkisi için hangisi doğrudur?', 'Bağımsızdırlar', ['Ayrıktırlar', 'A, B\'nin alt kümesidir', 'Birbirinin tümleyenidir'], 'P(A ∩ B) = 0,3 + 0,4 − 0,58 = 0,12\'dir ve bu değer 0,3 × 0,4 çarpımına eşittir; bu bağımsızlığın tanımıdır.'),
  ('P(A) = 0,5, P(B) = 0,6 ve P(A ∩ B) = 0,2 olan iki olay için B\'nin gerçekleştiğini öğrenmek A\'nın olasılığını nasıl etkiler?', 'Azaltır; P(A|B) yaklaşık 0,33 olur', ['Artırır; P(A|B) yaklaşık 0,67\'ye yükselir', 'Değiştirmez; olaylar bağımsızdır', 'A\'yı imkânsız kılar'], 'P(A|B) = 0,2/0,6 ≈ 0,33 olup P(A) = 0,5\'ten küçüktür; olaylar birbirini olumsuz etkiler.'),
  ('A ve B bağımsız olaylardır; P(A) = 0,3 ve P(B) = 0,6\'dır. Bu iki olaydan yalnızca birinin gerçekleşme olasılığı kaçtır?', '0,54', ['0,375', '0,18', '0,90'], 'P(A)P(B\') + P(A\')P(B) = 0,3 × 0,4 + 0,7 × 0,6 = 0,12 + 0,42 = 0,54 bulunur.'),
  ('A ile B bağımsızdır. P(A) = 0,5 ve P(A ∪ B) = 0,8 ise P(B) kaçtır?', '0,6', ['0,35', '0,5', '0,4'], '0,8 = 0,5 + P(B) − 0,5·P(B) eşitliğinden 0,5·P(B) = 0,3 ve P(B) = 0,6 bulunur.'),
  ('A ve B olaylarının C verildiğinde koşullu bağımsız olması hangi eşitlikle ifade edilir?', 'P(A ∩ B | C) = P(A|C)·P(B|C)', ['P(A ∩ B | C) = P(A ∩ B)·P(C) / P(A)', 'P(A|C) = P(B|C)', 'P(A ∩ B ∩ C) = P(C)'], 'Koşullu bağımsızlık, bağımsızlık tanımının C ile kısıtlanmış uzayda yazılmasıdır.'),
  ('Bir araştırmada kişilerin %30\'u sigara içiyor, %5\'inde belli bir hastalık var ve %3\'ü hem sigara içiyor hem bu hastalığa sahip. Sigara içen birinin bu hastalığa sahip olma olasılığı kaçtır?', '0,10', ['0,015', '0,05', '0,60'], 'P(H|S) = 0,03 / 0,30 = 0,10\'dur. Bu değer genel orandan (0,05) büyük olduğundan iki durum bağımsız değildir.'),
  ('Bağımsızlıkla ilgili aşağıdaki ifadelerden hangisi doğrudur?', 'A, B\'den bağımsızsa B de A\'dan bağımsızdır', ['Olasılığı sıfırdan büyük bağımsız iki olay ayrık olmalıdır', 'A, B\'den ve B, C\'den bağımsızsa A, C\'den de bağımsızdır', 'Bağımsız olayların kesişiminin olasılığı sıfırdır'], 'Tanım P(A ∩ B) = P(A)P(B) simetrik olduğundan bağımsızlık iki yönlüdür. Bağımsızlığın geçişme özelliği yoktur.'),
  ('Hilesiz bir para iki kez atılıyor. A = "birinci atış yazı" ve B = "iki atış farklı sonuç" olayları için hangisi doğrudur?', 'Bağımsızdırlar', ['Ayrıktırlar', 'Bağımlıdırlar; P(B|A) = 1\'dir', 'A, B\'nin alt kümesidir'], 'P(A) = 1/2, P(B) = 1/2 ve P(A ∩ B) = P(YT) = 1/4\'tür. Kesişim çarpıma eşit olduğundan olaylar bağımsızdır.'),
  ('Bir kargo şirketinde paketlerin %50\'si İstanbul, %30\'u Ankara, %20\'si İzmir deposundan çıkıyor. Gecikme oranları sırasıyla %4, %6 ve %12\'dir. Rastgele bir paketin gecikme olasılığı kaçtır?', '0,062', ['0,058', '0,0733', '0,22'], 'Toplam olasılık kuralıyla 0,5 × 0,04 + 0,3 × 0,06 + 0,2 × 0,12 = 0,02 + 0,018 + 0,024 = 0,062 bulunur.'),
  ('Paketlerin %50\'si İstanbul, %30\'u Ankara, %20\'si İzmir deposundan çıkan bir şirkette gecikme oranları sırasıyla %4, %6 ve %12\'dir. Geciken bir paketin çıkış deposu en yüksek olasılıkla hangisidir?', 'İzmir', ['İstanbul', 'Ankara', 'Üçü eşit olasılıklıdır'], 'Gecikmeli paket payları 0,020, 0,018 ve 0,024\'tür. Payı küçük olsa da gecikme oranı yüksek olan İzmir en büyük sonsal olasılığı alır.'),
  ('Bir testin duyarlılığı 0,90, özgüllüğü 0,95\'tir. Bu testin pozitif olabilirlik oranı kaçtır?', '18', ['0,95', '9,5', '0,857'], 'Pozitif olabilirlik oranı = duyarlılık / (1 − özgüllük) = 0,90 / 0,05 = 18\'dir.'),
  ('Bayes teoreminin bahis oranı (odds) biçimi hangisidir?', 'Sonsal oran = önsel oran × olabilirlik oranı', ['Sonsal oran = önsel oran + olabilirlik oranı', 'Sonsal olasılık = önsel olasılık × duyarlılık', 'Önsel oran = sonsal oran × olabilirlik oranı'], 'Kanıt gözlendikten sonraki oran, önceki oranın olabilirlik oranıyla çarpılmasıyla bulunur.'),
  ('Duyarlılığı ve özgüllüğü 0,9 olan bir test, hastalığın yaygınlığının %50 olduğu bir grupta uygulanıyor. Pozitif sonucun öngörü değeri kaçtır?', '0,9', ['0,5', '0,81', '0,45'], 'Hasta ve sağlıklı sayısı eşit olduğunda doğru pozitifler 0,45, yanlış pozitifler 0,05 olur; 0,45/0,50 = 0,9 bulunur.'),
  ('Bir tanı testinde yanlış pozitif oranı ile özgüllük arasındaki ilişki hangisidir?', 'Yanlış pozitif oranı = 1 − özgüllük', ['Yanlış pozitif oranı = 1 − duyarlılık', 'Yanlış pozitif oranı = özgüllük × duyarlılık', 'Yanlış pozitif oranı = özgüllük / yaygınlık'], 'Özgüllük sağlıklılarda negatif sonuç oranıdır; sağlıklılarda pozitif sonuç oranı bunun tümleyenidir.'),
  ('Bayes formülünde P(A|B) = P(B|A)P(A) / P(B) ifadesinin paydasındaki P(B) neyi temsil eder?', 'Kanıtın tüm olası nedenler üzerinden toplam olasılığını', ['Hipotezin önsel olasılığını', 'Hipotez doğru kabul edildiğinde kanıtın gözlenme olasılığını', 'Hipotezin sonsal olasılığını'], 'P(B), toplam olasılık kuralıyla bütün durumlar üzerinden hesaplanan normalleştirme terimidir; sonsal olasılıkların toplamını 1 yapar.'),
  ('İki torbadan biri yazı-tura ile seçiliyor. A torbasından kırmızı top çekme olasılığı 0,6, B torbasından 0,2\'dir. Çekilen top kırmızı ise A torbasının seçilmiş olma olasılığı kaçtır?', '0,75', ['0,6', '0,4', '0,375'], 'Önseller eşit olduğundan sonsallar olabilirliklerle orantılıdır: 0,6 / (0,6 + 0,2) = 0,75.'),
  ('Bir hastalığın yaygınlığı %4\'tür. Test hastaların %95\'inde pozitif, sağlıklıların %10\'unda yanlış pozitif sonuç veriyor. Toplumda testi pozitif çıkanların oranı kaçtır?', '0,134', ['0,038', '0,096', '0,0985'], 'P(+) = 0,04 × 0,95 + 0,96 × 0,10 = 0,038 + 0,096 = 0,134 bulunur.'),
  ('Bir bölgede günlerin %20\'si yağmurludur. Bir tahminci yağmurlu günlerin %90\'ında, kuru günlerin ise %20\'sinde "yağmur yağacak" diyor. Tahminci "yağmur yağacak" dediğinde yağmur yağma olasılığı yaklaşık kaçtır?', '0,53', ['0,90', '0,18', '0,346'], 'P(yağmur ∩ tahmin) = 0,18; P(tahmin) = 0,18 + 0,8 × 0,2 = 0,34\'tür. 0,18 / 0,34 ≈ 0,53 bulunur.'),
  ('Bayesçi güncellemede, aynı türden ve koşullu olarak bağımsız kanıtlar art arda geldiğinde her adımda ne yapılır?', 'Bir önceki sonsal, yeni adımın önseli olarak kullanılır', ['Her adımda ilk önsele geri dönülür', 'Olabilirlikler toplanıp önsele eklenir', 'Önsel olasılık, toplanan kanıt sayısına bölünerek yeniden hesaplanır'], 'Ardışık güncellemede o ana kadarki bilgi sonsal olasılıkta toplanır; yeni kanıt bu değerden başlanarak işlenir.'),
  ('Bir hastalığın yaygınlığı %0 ise duyarlılığı ve özgüllüğü yüksek bir testin pozitif sonucu için hangisi doğrudur?', 'Pozitif sonuçların tamamı yanlış pozitiftir', ['Pozitif sonuçların yarısı doğrudur', 'Pozitif öngörü değeri testin duyarlılığına eşit olur', 'Test hiç pozitif sonuç veremez'], 'Hasta yoksa doğru pozitif de olamaz; çıkan her pozitif sonuç sağlıklı birinde verilmiştir ve pozitif öngörü değeri 0\'dır.'),
  ('İki altın, iki gümüş ve bir altın bir gümüş para içeren üç kutuyla kurulan ünlü koşullu olasılık bulmacasını 1889\'da yayımlanan "Calcul des probabilités" kitabında ortaya koyan Fransız matematikçi kimdir?', 'Joseph Bertrand', ['Pierre-Simon Laplace', 'Blaise Pascal', 'Siméon Denis Poisson'], 'Bertrand\'ın kutu paradoksu adıyla bilinen bulmaca, Joseph Bertrand\'ın 1889 tarihli kitabında yer alır.'),
  ('İki çocuklu bir ailede büyük çocuğun kız olduğu biliniyor. Doğumlar bağımsız ve kız-erkek eşit olası ise iki çocuğun da kız olma olasılığı kaçtır?', '1/2', ['1/3', '7/12', '2/3'], 'Büyük çocuk belli olduğundan yalnız küçük çocuğun cinsiyeti belirsizdir; olasılık 1/2\'dir. "En az biri kız" bilgisinden farklı olarak hangi çocuğun kız olduğu bellidir.'),
  ('Üç çocuklu bir ailede en az bir kız çocuk olduğu biliniyor. Doğumlar bağımsız ve eşit olası ise üç çocuğun da kız olma olasılığı kaçtır?', '1/7', ['7/64', '1/4', '3/7'], '8 eşit olası diziden yalnız EEE dışlanır; kalan 7 dizinin yalnız biri KKK\'dır.'),
  ('Bir anne, üç çocuğundan en az ikisinin kız olduğunu söylüyor. Her doğumda kız ve erkek eşit olasılıklıysa annenin bütün çocuklarının kız olma ihtimali nedir?', '1/4', ['3/16', '1/2', '3/8'], 'En az iki kız içeren diziler KKE, KEK, EKK ve KKK olmak üzere 4 tanedir; bunlardan biri KKK\'dır.'),
  ('Birinci kutuda iki altın para, ikinci kutuda bir altın ve iki gümüş para vardır. Rastgele seçilen bir kutudan rastgele bir para alınıyor ve altın çıkıyor. Birinci kutunun seçilmiş olma olasılığı kaçtır?', '3/4', ['1/2', '2/3', '7/12'], 'P(altın | 1. kutu) = 1, P(altın | 2. kutu) = 1/3\'tür. Eşit önsellerle 1 / (1 + 1/3) = 3/4 bulunur.'),
  ('"İki çocuklu ailede en az biri kız" ile "iki çocuklu ailede büyük çocuk kız" bilgileri verildiğinde iki kız olasılığı farklı çıkar. Bu farkın nedeni nedir?', 'İki bilgi örnek uzayı farklı alt kümelere indirger', ['Doğumlar ikinci durumda bağımsız değildir', 'Birinci bilgi örnek uzayı genişletir', 'Kız ve erkek doğum olasılıkları iki durumda birbirinden farklıdır'], 'İlk bilgi {KK, KE, EK} kümesini, ikinci bilgi {KK, KE} kümesini bırakır; KK\'nın payı 1/3 ve 1/2 olur.'),
  ('Üç kapılı Monty Hall oyununda ödülün yerini bilen sunucu her zaman boş bir kapı açıp değiştirme hakkı tanıyor. Yarışmacı yazı-tura atarak değiştirip değiştirmemeye karar verirse kazanma olasılığı kaçtır?', '1/2', ['1/3', '2/3', '5/12'], 'Değiştirmek 2/3, kalmak 1/3 olasılıkla kazandırır. Eşit olasılıklı karışım (1/2)(2/3) + (1/2)(1/3) = 1/2 verir.'),
  ('Bir kutuda biri iki yüzü kırmızı, biri iki yüzü mavi, biri de bir yüzü kırmızı bir yüzü mavi üç disk vardır. Rastgele seçilen disk atılıyor ve üst yüz mavi geliyor. Diskin karışık renkli disk olma olasılığı kaçtır?', '1/3', ['1/2', '2/3', '5/12'], 'Görülebilecek üç mavi yüzden yalnız biri karışık diske aittir; olasılık 1/3\'tür.'),
  ('Beş kapılı bir oyunda yarışmacı bir kapı seçiyor. Ödülün yerini bilen sunucu kalan dört kapıdan üç boş kapıyı açıyor ve değiştirme hakkı veriyor. Değiştiren yarışmacının kazanma olasılığı kaçtır?', '4/5', ['1/2', '15/16', '2/5'], 'İlk seçim 1/5 olasılıkla doğrudur; değiştirmek ancak ilk seçim yanlışsa kazandırır ve kalan tek kapalı kapı o durumda kesin ödüldür: 4/5.'),
  ('Bir arkadaşınız arkanız dönükken iki zar atıyor ve "Zarlardan en az biri 5" diyor. Bu durumda zarlardaki sayıların toplamının 9 olma ihtimali nedir?', '2/11', ['11/36', '1/6', '4/11'], 'En az bir 5 içeren 11 sıralı sonuç vardır. Bunlardan (4, 5) ve (5, 4) toplamı 9 yapar.'),
  ('Üç zar atılıyor. Üst yüzlerin toplamının 5 ya da daha küçük olma olasılığı kaçtır?', '5/108', ['13/216', '1/54', '7/216'], 'Toplam 3 için 1, toplam 4 için 3, toplam 5 için 6 sıralı sonuç vardır; 10/216 = 5/108.'),
  ('Kırmızı ve beyaz iki zarın üst yüzlerinin toplamı 6 olarak okunuyor. Sayılardan en az birinin 3 olması hangi olasılıkla gerçekleşmiştir?', '1/5', ['1/6', '2/5', '1/11'], 'Toplamı 6 olan 5 sıralı sonuç vardır: (1,5), (2,4), (3,3), (4,2), (5,1). Yalnız (3, 3) koşulu sağlar.'),
  ('Hilesiz bir zar dört kez atılıyor. Dört sonucun birbirinden farklı olma olasılığı kaçtır?', '5/18', ['25/72', '5/9', '5/12'], '6 × 5 × 4 × 3 = 360 uygun dizi vardır; 360 / 6⁴ = 360/1296 = 5/18.'),
  ('Barbut (craps) oyununun ilk atışında iki zarın toplamı 7 ya da 11 gelirse oyuncu hemen kazanır. İlk atışta hemen kazanma olasılığı kaçtır?', '2/9', ['1/6', '1/18', '7/36'], 'Toplam 7 için 6, toplam 11 için 2 sonuç vardır; 8/36 = 2/9.'),
  ('Masaya atılan iki zarın toplamının tek sayı olduğu öğreniliyor. Zarlardan birinin üst yüzünde 1 bulunması hangi olasılıkla doğrudur?', '1/3', ['1/6', '1/2', '11/36'], 'Tek toplam veren 18 sonuç vardır. Bunlardan bir zarı 1 olanlar (1,2), (1,4), (1,6), (2,1), (4,1), (6,1) olmak üzere 6 tanedir.'),
  ('Hilesiz bir zar altı kez atılıyor. Her yüzün tam bir kez gelme olasılığı yaklaşık kaçtır?', '0,015', ['0,167', '0,0002', '0,105'], 'Uygun dizi sayısı 6! = 720\'dir; 720 / 6⁶ = 720/46656 ≈ 0,0154 bulunur.'),
  ('Bir zar atılıyor; sonuç 1 ya da 2 ise birinci torbadan (2 kırmızı, 2 beyaz), aksi hâlde ikinci torbadan (1 kırmızı, 4 beyaz) bir top çekiliyor. Çekilen topun kırmızı olma olasılığı kaçtır?', '3/10', ['11/30', '1/5', '7/15'], '(1/3)(1/2) + (2/3)(1/5) = 1/6 + 2/15 = 9/30 = 3/10 bulunur.'),
  ('İki zar atılıyor ve iki zarın farklı sayılar gösterdiği biliniyor. Toplamın 7 olma olasılığı kaçtır?', '1/5', ['1/6', '1/30', '7/30'], 'Farklı sayı gösteren 30 sonuç vardır. Toplamı 7 olan 6 sonucun hepsinde zarlar farklıdır: 6/30 = 1/5.'),
  ('Hilesiz bir para dört kez atılıyor. Art arda gelen hiçbir iki atışın aynı sonucu vermeme, yani sonuçların sürekli değişme olasılığı kaçtır?', '1/8', ['1/16', '1/4', '3/16'], 'Uygun diziler yalnız YTYT ve TYTY\'dir: 2/16 = 1/8.'),
  ('Hilesiz bir para üç kez atılıyor ve en az bir yazı geldiği biliniyor. En az iki yazı gelmiş olma olasılığı kaçtır?', '4/7', ['1/2', '3/7', '11/14'], 'P(en az iki yazı) = 4/8, P(en az bir yazı) = 7/8\'dir. Koşullu olasılık 4/7 bulunur.'),
  ('Ali ve Banu ikişer hilesiz para atıyor. İkisinin elde ettiği yazı sayılarının eşit olma olasılığı kaçtır?', '3/8', ['1/4', '1/2', '5/16'], 'Yazı sayısı 0, 1, 2 için olasılıklar 1/4, 1/2, 1/4\'tür. Eşitlik olasılığı (1/4)² + (1/2)² + (1/4)² = 6/16 = 3/8\'dir.'),
  ('52\'lik desteden yerine koymadan iki kart çekiliyor. Kartlardan en az birinin as olma olasılığı kaçtır?', '33/221', ['2/13', '1/221', '4/51'], 'Hiç as gelmeme olasılığı (48/52)(47/51) = 188/221\'dir. Tümleyeni 33/221 olur.'),
  ('Poker\'de 52 karttan dağıtılan 5 kartlık bir elde aynı değerden dört kart bulunmasına "kare" denir. Kare içeren kaç farklı el vardır?', '624', ['13', '48', '2496'], 'Dört kartın değeri 13 biçimde seçilir, beşinci kart kalan 48 karttan biridir: 13 × 48 = 624.'),
  ('İyice karılmış 52\'lik bir deste tek tek açılıyor. Dört as içinde ilk açılanın maça ası olma olasılığı kaçtır?', '1/4', ['1/52', '1/13', '4/13'], 'Dört asın kendi aralarındaki sıralanışı simetriktir; her birinin ilk olma olasılığı eşittir.'),
  ('52\'lik desteden yerine koymadan üç kart çekiliyor. Üç kartın da birbirinden farklı değerlerde (as, 2, …, papaz) olma olasılığı yaklaşık kaçtır?', '0,83', ['0,70', '0,94', '0,6923'], 'İkinci kart için 48/51, üçüncü kart için 44/50 olasılık vardır: (48/51)(44/50) ≈ 0,828.'),
  ('Bir torbada 1 kırmızı ve 1 mavi top vardır. Her çekilişte çekilen top, aynı renkten bir top daha eklenerek torbaya geri konuyor (Pólya torbası). İkinci çekilişte kırmızı gelme olasılığı kaçtır?', '1/2', ['2/3', '1/3', '5/12'], 'İlk top kırmızıysa olasılık 2/3, maviyse 1/3 olur: (1/2)(2/3) + (1/2)(1/3) = 1/2. Renkler simetrik olduğundan sonuç değişmez.'),
  ('1 kırmızı ve 1 mavi topla başlayan bir Pólya torbasında her çekilen top, aynı renkten bir topla birlikte geri konuyor. İlk üç çekilişin üçünde de kırmızı gelme olasılığı kaçtır?', '1/4', ['1/8', '1/3', '3/16'], 'Çarpma kuralıyla (1/2)(2/3)(3/4) = 1/4 bulunur. Her kırmızı çekiliş sonraki kırmızı olasılığını artırır.'),
  ('Pólya torbası modelinde çekilen topun aynı renkten bir topla geri konması ardışık çekilişler için ne anlama gelir?', 'Çekilişler bağımlıdır; bir rengin çıkması o rengin olasılığını artırır', ['Çekilişler bağımsızdır ve olasılıklar sabittir', 'Her çekiliş bir önceki rengin olasılığını azaltır', 'Torbadaki toplam top sayısı hiç değişmediği için olasılıklar aynı kalır'], 'Kırmızı çekildiğinde torbadaki kırmızı oranı yükselir; bu "zengin daha da zenginleşir" etkisi pozitif bağımlılık yaratır.'),
  ('Bir torbada 2 kırmızı 2 mavi top vardır. Çekilen top geri konmuyor; onun yerine karşı renkten bir top ekleniyor. İlk iki çekilişin ikisinde de kırmızı gelme olasılığı kaçtır?', '1/8', ['1/6', '1/4', '3/16'], 'İlk kırmızıdan sonra torbada 1 kırmızı 3 mavi kalır: (1/2)(1/4) = 1/8.'),
  ('Yedi kişilik bir gruptan rastgele 3 kişilik bir kurul seçiliyor. Ali ile Veli\'nin ikisinin de kurulda yer alma olasılığı kaçtır?', '1/7', ['2/7', '3/7', '1/21'], 'İkisi kurulda olduğunda üçüncü üye kalan 5 kişiden seçilir: C(5, 1)/C(7, 3) = 5/35 = 1/7.'),
  ('Yedi kişiden rastgele 3 kişilik bir kurul oluşturuluyor. Ali\'nin kurulda bulunup Veli\'nin bulunmama olasılığı kaçtır?', '2/7', ['1/7', '3/7', '4/35'], 'Ali seçilmiş, Veli dışarıda ise kalan iki üye diğer 5 kişiden seçilir: C(5, 2)/C(7, 3) = 10/35 = 2/7.'),
  ('On öğrenci rastgele beşer kişilik iki gruba ayrılıyor. Belirli iki öğrencinin aynı grupta olma olasılığı kaçtır?', '4/9', ['9/20', '1/5', '5/9'], 'Birinci öğrencinin grubunda kalan 4 yer, diğer 9 öğrenci arasından doldurulur; ikinci öğrencinin bu yerlerden birine düşme olasılığı 4/9\'dur.'),
  ('Bir öğretmen 12 öğrencilik sınıfını kura ile dörder kişilik üç çalışma grubuna bölüyor. Ece ile Selin\'in aynı gruba düşme ihtimali nedir?', '3/11', ['1/3', '5/12', '4/11'], 'Birinci öğrencinin grubunda 3 boş yer vardır ve diğer 11 öğrenci eşit şansa sahiptir: 3/11.'),
  ('Bir torbada 1 kırmızı ve 4 beyaz top var. İki oyuncu sırayla ve yerine koymadan birer top çekiyor; kırmızıyı çeken kazanıyor. Oyuna ilk başlayanın kazanma olasılığı kaçtır?', '3/5', ['7/10', '1/5', '2/5'], 'Kırmızı topun sırası 1\'den 5\'e eşit olasılıklıdır. İlk oyuncu 1., 3. ve 5. çekilişleri yapar: 3/5.'),
  ('Altı kişi rastgele sıraya giriyor. Ali, Banu ve Can\'ın aralarında başkaları olabilecek biçimde tam bu sırayla dizilmiş olma olasılığı kaçtır?', '1/6', ['1/3', '1/20', '1/120'], 'Üç kişinin birbirine göre 3! = 6 sıralanışı eşit olasılıklıdır ve yalnız biri istenen sıradır.'),
  ('Beş kişi düz bir sıraya rastgele diziliyor. Emre ile Fatma arasında tam olarak bir kişi bulunma olasılığı kaçtır?', '3/10', ['2/5', '3/25', '3/20'], 'İkisinin yerleri 5 × 4 = 20 sıralı biçimde seçilir. Arada bir kişi olan yer çiftleri (1,3), (2,4), (3,5) ve tersleri olmak üzere 6 tanedir: 6/20 = 3/10.'),
  ('Bir sekreter dört davetiyeyi adresleri yazılı dört zarfa bakmadan yerleştiriyor. Davetiyelerden yalnızca birinin yanlış zarfa düşmesi, yani tam üçünün doğru yerde olması hangi olasılıkla gerçekleşir?', '0', ['1/24', '1/6', '1/8'], 'Üç mektup doğru yerdeyse kalan tek zarf da dördüncü mektubun kendi zarfıdır; tam üç doğru yerleşim imkânsızdır.'),
  ('Dört kişi şapkalarını vestiyere bırakıyor ve çıkışta şapkalar rastgele dağıtılıyor. Tam olarak iki kişinin kendi şapkasını alma olasılığı kaçtır?', '1/4', ['1/6', '3/8', '1/12'], 'Doğru alan iki kişi C(4, 2) = 6 biçimde seçilir, diğer ikisi şapkaları değiş tokuş etmelidir: 6/24 = 1/4.'),
  ('Üç arkadaş hediyeleşmek için adlarını bir torbaya atıp sırayla birer ad çekiyor. Kimsenin kendi adını çekmeme olasılığı kaçtır?', '1/3', ['5/12', '1/6', '2/9'], '3! = 6 eşleşmeden yalnız iki döngüsel eşleşmede kimse kendi adını çekmez: 2/6 = 1/3.'),
  ('Doğum günlerinin 365 güne eşit dağıldığı varsayılırsa, gruptaki en az iki kişinin aynı gün doğmuş olma olasılığı yaklaşık kaç kişilik grupta %99\'u geçer?', '57', ['183', '40', '366'], 'Olasılık 23 kişide %50\'yi, 57 kişide yaklaşık %99\'u aşar. Kesinlik ise ancak 366 kişide sağlanır.'),
  ('23 kişilik bir grupta ortak doğum günü olasılığının sezgiye göre yüksek (yaklaşık 0,5) çıkmasının temel nedeni, bu grupta kaç farklı kişi ikilisi bulunmasıdır?', '253', ['23', '1058', '529'], '23 kişiden C(23, 2) = 253 ikili oluşur ve her ikili eşleşme fırsatı yaratır.'),
  ('[0, 1] aralığından bağımsız ve düzgün iki sayı seçiliyor. Sayılar arasındaki farkın mutlak değerinin 1/2\'den küçük olma olasılığı kaçtır?', '3/4', ['11/16', '1/4', '5/8'], 'Farkın 1/2\'yi aştığı bölgeler birim karenin iki köşesinde alanı 1/8 olan iki üçgendir. 1 − 2/8 = 3/4 bulunur.'),
  ('Kenarı 1 birim olan bir kare içinden rastgele bir nokta seçiliyor. Noktanın en yakın kenara uzaklığının 1/4 birimden az olma olasılığı kaçtır?', '3/4', ['1/4', '1/2', '7/16'], 'Bütün kenarlara en az 1/4 uzaklıktaki noktalar kenarı 1/2 olan iç kareyi oluşturur; alanı 1/4\'tür. Tümleyen 3/4\'tür.'),
  ('Bir trafik ışığının 100 saniyelik döngüsünde ışık 60 saniye yeşil, 5 saniye sarı, 35 saniye kırmızı yanıyor. Rastgele bir anda gelen bir sürücü ışığı yeşil görmediğine göre ışığın kırmızı olma olasılığı kaçtır?', '7/8', ['7/20', '1/8', '35/65'], 'Yeşil olmayan süre 40 saniyedir ve bunun 35 saniyesi kırmızıdır: 35/40 = 7/8.'),
  ('İki atıcı sırayla hedefe birer atış yapıyor ve ilk isabet ettiren kazanıyor. İkisinin de isabet olasılığı her atışta 1/2\'dir ve atışlar bağımsızdır. İlk atan oyuncunun kazanma olasılığı kaçtır?', '2/3', ['1/2', '3/4', '7/12'], 'İlk oyuncu 1., 3., 5., … atışlarda kazanabilir: 1/2 + 1/8 + 1/32 + … = (1/2)/(1 − 1/4) = 2/3.'),
  ('İki oyuncu sırayla hilesiz bir zar atıyor; ilk 6 atan kazanıyor. Oyuna başlayan oyuncunun kazanma olasılığı kaçtır?', '6/11', ['1/2', '1/6', '25/36'], 'İlk oyuncu için olasılık (1/6) / (1 − 25/36) = (1/6)(36/11) = 6/11\'dir.'),
  ('İki takımdan ilk iki galibiyete ulaşanın kazandığı üç maçlık bir seride A takımı her maçı bağımsız olarak 0,6 olasılıkla kazanıyor. A\'nın seriyi kazanma olasılığı kaçtır?', '0,648', ['0,6', '0,36', '0,7056'], 'A ya ilk iki maçı alır (0,36) ya da 1-1\'den sonra üçüncüyü kazanır (2 × 0,6 × 0,4 × 0,6 = 0,288): toplam 0,648.'),
  ('İlk dört galibiyete ulaşanın kazandığı yedi maçlık bir seride iki takım eşit güçtedir ve maçlar bağımsızdır. Serinin dört maçta bitme olasılığı kaçtır?', '1/8', ['1/16', '1/4', '5/16'], 'Takımlardan biri ilk dört maçı kazanmalıdır: 2 × (1/2)⁴ = 1/8.'),
  ('Üç puana ilk ulaşanın 64 altını alacağı adil bir oyunda A 2, B 1 puandayken oyun yarıda kesiliyor. Pascal ve Fermat\'nın çözümüne göre A\'ya kaç altın düşer?', '48', ['42,67', '42', '56'], 'A\'nın bir, B\'nin iki puana ihtiyacı vardır. B ancak sonraki iki turu da kazanırsa kazanır (1/4). A\'nın payı 64 × 3/4 = 48 altındır.'),
  ('Adil bir oyunda kazanmak için A\'nın 1, B\'nin 3 puana daha ihtiyacı varken oyun kesiliyor. Ortaya konan 80 altın kazanma olasılıklarına göre bölüşülürse A\'nın payı kaç altın olur?', '70', ['60', '40', '72,5'], 'B ancak art arda üç turu kazanırsa kazanır: (1/2)³ = 1/8. A\'nın olasılığı 7/8\'dir ve payı 80 × 7/8 = 70 altındır.'),
  ('Sayı doğrusunda 0\'dan başlayan bir parçacık her adımda eşit olasılıkla 1 birim sağa ya da sola gidiyor. Dört adım sonra yeniden 0 noktasında olma olasılığı kaçtır?', '3/8', ['1/4', '1/2', '5/16'], 'İki sağ ve iki sol adım gerekir: C(4, 2)/2⁴ = 6/16 = 3/8.'),
  ('0\'dan başlayan ve her adımda eşit olasılıkla +1 ya da −1 hareket eden bir parçacığın altı adım sonra +2 konumunda olma olasılığı kaçtır?', '15/64', ['5/16', '35/64', '1/4'], 'Dört +1 ve iki −1 adım gerekir: C(6, 4)/2⁶ = 15/64.'),
  ('İki oyuncu sırayla hilesiz bir para atıyor ve ilk yazı atan kazanıyor. Oyunun başlayan oyuncu lehine olmasının nedeni nedir?', 'İlk oyuncu, ikincinin her kazanma fırsatından önce aynı şansı bir kez fazla kullanır', ['Oyunun ilk atışında yazı gelme olasılığı sonraki atışlardan daha yüksektir', 'Para atışları önceki sonuçlara bağlıdır', 'İkinci oyuncu için yazı olasılığı 1/4\'tür'], 'Her turda önce birinci oyuncu denediği için o oyuncunun kazanma olasılığı ikincinin iki katı olur (2/3\'e 1/3).'),
  ('Bir kentte yağmurlu bir günü 0,7 olasılıkla yine yağmurlu bir gün izliyor ve havanın ertesi günü yalnız o günün havasına bağlı. Bugün yağmur yağıyorsa sonraki üç günün kesintisiz yağmurlu geçme olasılığı kaçtır?', '0,343', ['0,7', '0,21', '0,0270'], 'Her geçiş bir öncekine koşullu olarak 0,7 olasılıklıdır; zincir boyunca çarpılır: 0,7³ = 0,343.'),
  ('Bir dergi abonelerinin %90\'ı ertesi ay aboneliğini sürdürüyor; abone olmayanların %20\'si ertesi ay abone oluyor. Bu ay abone olan birinin iki ay sonra abone olma olasılığı kaçtır?', '0,83', ['0,81', '0,729', '0,72'], 'Abone kalıp kalmak: 0,9 × 0,9 = 0,81; ayrılıp geri dönmek: 0,1 × 0,2 = 0,02. Toplam 0,83\'tür.'),
  ('Heterozigot (Aa) bir birey ile homozigot çekinik (aa) bir bireyin iki çocuğu oluyor. İki çocuğun da çekinik fenotipli olma olasılığı kaçtır?', '1/4', ['1/2', '1/16', '1/8'], 'Her çocuk için olasılık 1/2\'dir ve çocuklar bağımsızdır: (1/2)² = 1/4.'),
  ('X kromozomuna bağlı renk körlüğü için taşıyıcı bir anne ile renk körü olmayan bir babanın doğacak çocuğunun renk körü bir erkek olma olasılığı kaçtır?', '1/4', ['1/2', '3/16', '0'], 'Çocuğun erkek olma olasılığı 1/2, annenin hastalık alelini aktarma olasılığı 1/2\'dir: 1/4.'),
  ('İki özellik bakımından heterozigot (AaBb) iki birey çaprazlanıyor ve genler bağımsız kalıtılıyor. Yavrunun iki özellik bakımından da çekinik (aabb) olma olasılığı kaçtır?', '1/16', ['1/4', '3/64', '9/16'], 'Her özellik için çekinik olma olasılığı 1/4\'tür ve bağımsızdır: (1/4)(1/4) = 1/16.'),
  ('Kan grubu genotipleri AO ve BO olan iki ebeveynin çocuğunun AB kan grubundan olma olasılığı kaçtır?', '1/4', ['1/2', '3/16', '1/8'], 'Çocuk anneden A\'yı 1/2, babadan B\'yi 1/2 olasılıkla alır: 1/4. O, A ve B grupları da 1/4\'er olasılıklıdır.'),
  ('0000 ile 9999 arasındaki dört haneli kodlardan biri rastgele seçiliyor. Kodun dört rakamının birbirinden farklı olma olasılığı kaçtır?', '0,504', ['0,5', '0,4096', '0,6561'], 'Farklı rakamlı kod sayısı 10 × 9 × 8 × 7 = 5040\'tır: 5040/10.000 = 0,504.'),
  ('p küçük olmak üzere bağımsız n denemede bir olayın en az bir kez gerçekleşme olasılığı 1 − (1 − p)ⁿ için np çarpımı ne zaman iyi bir yaklaşımdır?', 'np değeri 1\'e göre küçükken', ['n küçük ve p büyükken', 'np değeri 1\'den büyükken', 'Her n ve p için tam olarak eşittir'], '1 − (1 − p)ⁿ ≈ np yaklaşımı ancak np küçükken iyidir; np büyüdükçe olasılığı fazla tahmin eder ve 1\'i bile aşabilir.'),
  ('Bir sistemde çalışma olasılıkları 0,9 ve 0,8 olan A ve B parçaları birbirine paralel bağlıdır; bu blok, çalışma olasılığı 0,95 olan C parçasıyla seri bağlıdır. Parçalar bağımsızsa sistemin çalışma olasılığı kaçtır?', '0,931', ['0,684', '0,98', '0,9025'], 'Paralel blok 1 − 0,1 × 0,2 = 0,98 olasılıkla çalışır. Seri bağlantıda 0,98 × 0,95 = 0,931 bulunur.'),
  ('Çalışma olasılıkları 0,9 olan A ve B parçaları seri bağlanmış; bu kol, çalışma olasılığı 0,8 olan C parçasına paralel bağlanmıştır. Parçalar bağımsızsa sistemin çalışma olasılığı kaçtır?', '0,962', ['0,648', '0,81', '0,9504'], 'Seri kol 0,81 olasılıkla çalışır. Paralel bağlantıda sistem 1 − (1 − 0,81)(1 − 0,8) = 1 − 0,038 = 0,962 olasılıkla çalışır.'),
  ('Bir öğrenci aynı deney için P(A) = 0,3, P(B) = 0,4 ve P(A ∩ B) = 0,35 değerlerini yazmıştır. Bu atama için hangisi doğrudur?', 'Tutarsızdır, çünkü kesişim A\'nın olasılığını aşamaz', ['Tutarlıdır; olaylar bağımlıdır ve kesişim büyüktür', 'Tutarlıdır; olaylar bağımsızdır', 'Tutarsızdır, çünkü P(A) + P(B) 1\'den küçüktür'], 'A ∩ B ⊂ A olduğundan P(A ∩ B) ≤ 0,3 olmalıdır; 0,35 bu sınırı aşar.'),
  ('Bir penaltıcı şutlarının %10\'unu çerçeve dışına atıyor. Çerçeveyi bulan şutlarda kaleci 0,5 olasılıkla doğru köşeye atlıyor ve doğru köşeye atladığında 0,3 olasılıkla kurtarıyor; yanlış köşeye atlarsa kurtaramıyor. Penaltının gol olma olasılığı kaçtır?', '0,765', ['0,9', '0,85', '0,6885'], 'Çerçeveyi bulup kurtarılmama olasılığı 0,9 × (1 − 0,5 × 0,3) = 0,9 × 0,85 = 0,765\'tir.'),
  ('Bir öğrenci beş seçenekli sorulardan birinin yanıtını 0,6 olasılıkla biliyor, bilmediğinde seçeneklerden birini şans eseri seçiyor. Bu soruyu doğru işaretleme olasılığı kaçtır?', '0,68', ['0,60', '0,80', '0,725'], 'Toplam olasılık kuralıyla 0,6 × 1 + 0,4 × (1/5) = 0,68 bulunur.'),
  ('Galileo\'nun ele aldığı soruda olduğu gibi üç zar birlikte atılıyor. Zarlardaki sayıların toplamının 9 çıkma olasılığı nedir?', '25/216', ['125/1296', '27/216', '5/54'], 'Toplamı 9 yapan sıralı üçlülerin sayısı 25\'tir: 25/216.'),
  ('"Olasılık kuramı, aslında hesaba indirgenmiş sağduyudan başka bir şey değildir." sözü hangi matematikçiye aittir?', 'Pierre-Simon Laplace', ['Blaise Pascal', 'Gottfried Wilhelm Leibniz', 'Andrey Kolmogorov'], 'Bu söz Laplace\'ın 1814 tarihli "Olasılıklar Üzerine Felsefi Deneme" adlı eserinde geçer.'),
  ('Bir deney 10 kez yapılmış ve 10\'unda da başarı elde edilmiştir. Laplace\'ın ardıllık kuralına göre on birinci denemenin başarılı olma olasılığı kaçtır?', '11/12', ['1', '10/11', '10/12'], 'Kural (s + 1)/(n + 2) = (10 + 1)/(10 + 2) = 11/12 verir; hiç başarısızlık görülmemiş olsa da olasılık 1 alınmaz.'),
  ('Efron zarları olarak bilinen dört özel zar takımında A, B\'yi; B, C\'yi; C, D\'yi ve D, A\'yı 2/3 olasılıkla yener. Bu örnek neyi gösterir?', '"Daha olasılıkla yenme" ilişkisinin geçişli olmayabileceğini', ['Zarların hileli olduğunu', 'Her zar çiftinde kazanma olasılığının 1/2 olduğunu', 'Beklenen değeri büyük olan zarın her karşılaşmada mutlaka kazandığını'], 'Olasılıkla üstünlük geçişli değildir; ikinci oynayan oyuncu, rakibin seçtiği zarı yenen zarı seçerek avantaj sağlar.'),
  ('Bir gofret markası kutularına üç farklı oyuncaktan birini eşit olasılıkla koyuyor. Üç kutu alan birinin üç farklı oyuncağın hepsini elde etme olasılığı kaçtır?', '2/9', ['1/3', '1/9', '8/27'], 'Uygun dizi sayısı 3! = 6, toplam dizi 3³ = 27\'dir: 6/27 = 2/9.'),
  ('Olasılık üzerine İngilizce yazılmış ilk kapsamlı ders kitaplarından biri olan "The Doctrine of Chances" (1718) adlı eserin yazarı kimdir?', 'Abraham de Moivre', ['Jakob Bernoulli', 'Thomas Bayes', 'Daniel Bernoulli ve Leonhard Euler'], 'Fransız asıllı İngiliz matematikçi de Moivre bu eseri 1718\'de yayımlamıştır.'),
  ('Sonuçları birbirinden ayırt etmek için hiçbir neden yoksa onlara eşit olasılık verilmesini öngören ilkeye ne ad verilir?', 'Yetersiz neden (kayıtsızlık) ilkesi', ['Büyük sayılar ilkesi', 'En çok olabilirlik (maksimum olabilirlik) ilkesi', 'Güvercin yuvası ilkesi'], 'Laplace\'ın klasik tanımı bu ilkeye dayanır; Keynes buna "kayıtsızlık ilkesi" adını vermiştir.'),
  ('Hilesiz bir zar atılıyor ve sonucun çift olduğu söyleniyor. Bu bilgiye göre üst yüzdeki sayının beklenen değeri kaçtır?', '4', ['3,5', '3', '5'], 'Koşullu dağılımda 2, 4 ve 6 eşit olasılıklıdır; ortalamaları (2 + 4 + 6)/3 = 4\'tür.'),
  ('Bir sınıfta öğrencilerin %30\'u matematikten, %20\'si fizikten, %10\'u her iki dersten kalmıştır. Matematikten kalan bir öğrencinin fizikten geçmiş olma olasılığı kaçtır?', '2/3', ['7/15', '1/2', '4/5'], 'Matematikten kalıp fizikten geçenlerin oranı 0,30 − 0,10 = 0,20\'dir. 0,20 / 0,30 = 2/3 bulunur.'),
  ('Bir futbol takımı yağmurlu maçların %40\'ını, kuru havada oynanan maçların %60\'ını kazanıyor. Maçların %25\'i yağmurlu havada oynanıyor. Takımın kazandığı bir maçın yağmurlu havada oynanmış olma olasılığı kaçtır?', '2/11', ['9/22', '2/5', '9/11'], 'P(yağmur ∩ galibiyet) = 0,25 × 0,4 = 0,10; P(galibiyet) = 0,10 + 0,75 × 0,6 = 0,55\'tir. 0,10/0,55 = 2/11.'),
  ('Bir kütüphanedeki kitapların %70\'i Türkçedir. Türkçe kitapların %20\'si, yabancı dildeki kitapların %50\'si romandır. Rastgele seçilen bir romanın Türkçe olma olasılığı yaklaşık kaçtır?', '0,48', ['0,70', '0,14', '0,2917'], 'P(Türkçe ∩ roman) = 0,14; P(roman) = 0,14 + 0,15 = 0,29\'dur. 0,14 / 0,29 ≈ 0,48 bulunur.'),
  ('P(B) > 0 olmak üzere P(A|B) = 1 eşitliği neyi anlatır?', 'B gerçekleştiğinde A\'nın da kesin olarak gerçekleştiğini', ['A gerçekleştiğinde B\'nin de kesin olarak gerçekleştiğini gösterir', 'A\'nın kesin olay olduğunu', 'A ile B\'nin bağımsız olduğunu'], 'P(A ∩ B) = P(B) demektir; B\'nin olasılıklı her parçası A\'nın içindedir. A\'nın kendisi kesin olmak zorunda değildir.'),
  ('Üç olay için çarpma kuralının genel biçimi hangisidir?', 'P(A ∩ B ∩ C) = P(A)·P(B|A)·P(C|A ∩ B)', ['P(A ∩ B ∩ C) = P(A)·P(B)·P(C)', 'P(A ∩ B ∩ C) = P(A|B)·P(B|C)·P(C|A)', 'P(A ∩ B ∩ C) = P(A) + P(B|A) + P(C|A ∩ B)'], 'Her adımda önceki olayların gerçekleştiği bilgisi koşul olarak eklenir; bağımsızlık varsayımı gerekmez.'),
  ('Üç ayrık hipotez için önsel × olabilirlik çarpımları 0,02, 0,03 ve 0,05 olarak hesaplanmıştır. Üçüncü hipotezin sonsal olasılığı kaçtır?', '0,5', ['0,05', '0,3', '0,333'], 'Çarpımlar toplamı 0,10\'dur; normalleştirme ile 0,05 / 0,10 = 0,5 bulunur.'),
  ('Bir kanıtın olabilirlik oranı 1 ise bu kanıt gözlendikten sonra hipotezin olasılığı nasıl değişir?', 'Değişmez; sonsal önsele eşit kalır', ['Kanıt gözlendiği için iki katına çıkar', '1\'e eşit olur', 'Yarıya iner'], 'Kanıt iki hipotez altında eşit olasılıklıysa ayırt edici bilgi taşımaz; sonsal oran önsel oranla aynı kalır.'),
  ('Duyarlılığı 0,8 ve özgüllüğü 0,9 olan bir testin negatif olabilirlik oranı yaklaşık kaçtır?', '0,22', ['0,11', '8', '0,889'], 'Negatif olabilirlik oranı = (1 − duyarlılık) / özgüllük = 0,2 / 0,9 ≈ 0,22\'dir; 1\'den küçük olduğu için negatif sonuç hastalık olasılığını düşürür.'),
  ('A ile B ayrık olaylardır; P(A) = 0,2 ve P(B) = 0,3\'tür. A ya da B\'nin gerçekleştiği bilindiğinde A\'nın gerçekleşmiş olma olasılığı kaçtır?', '0,4', ['0,2', '0,6', '0,667'], 'P(A | A ∪ B) = P(A) / P(A ∪ B) = 0,2 / 0,5 = 0,4 bulunur.'),
  ('18. ve 19. yüzyılda, gözlenen sonuçlardan nedenlerin olasılığına geçen Bayes-Laplace yöntemine verilen ad hangisidir?', 'Ters olasılık', ['Geometrik olasılık', 'Frekansçı olasılık', 'Klasik olasılık'], 'Nedenden sonuca değil, sonuçtan nedene giden bu yaklaşım tarihsel olarak "ters olasılık" (inverse probability) adıyla anılmıştır.'),
  ('P(A|B) ile P(A|B\') arasındaki fark büyüdükçe A ile B arasındaki ilişki için ne söylenebilir?', 'B\'yi bilmek A hakkında daha çok bilgi verir', ['Olaylar giderek daha bağımsız hâle gelir ve ilişki zayıflar', 'Olaylar ayrık olmak zorundadır', 'P(A) değeri 1\'e yaklaşır'], 'Bağımsızlıkta iki koşullu olasılık eşittir. Aralarındaki fark, B\'nin gerçekleşip gerçekleşmemesinin A\'nın olasılığını ne kadar değiştirdiğini gösterir.'),
  ('Bir anket sorusunda katılımcıların %60\'ı "evet" diyor. "Evet" diyenlerin %25\'i, "hayır" diyenlerin %50\'si kentsel bölgede yaşıyor. Kentsel bölgede yaşayan bir katılımcının "evet" demiş olma olasılığı kaçtır?', '3/7', ['3/5', '9/20', '4/7'], 'P(evet ∩ kent) = 0,15, P(hayır ∩ kent) = 0,20\'dir. 0,15 / 0,35 = 3/7 bulunur.'),
  ('Bir olasılık ağacında ilk aşamada A\'nın olasılığı 0,4\'tür. A\'dan sonra B\'nin koşullu olasılığı 0,5, A\' olayından sonra B\'nin koşullu olasılığı 0,5\'tir. Bu ağaç A ile B için neyi gösterir?', 'A ile B bağımsızdır', ['A ile B ayrıktır', 'B, A\'nın alt kümesidir', 'P(B) = 0,2\'dir'], 'B\'nin koşullu olasılığı A\'nın gerçekleşip gerçekleşmemesine göre değişmiyor; bu da P(B|A) = P(B) yani bağımsızlık demektir.'),
  ('On kişi, eşit aralıklı on sandalyesi olan yuvarlak bir masaya rastgele oturuyor. İki belirli kişinin tam karşı karşıya oturma olasılığı kaçtır?', '1/9', ['1/10', '2/9', '1/45'], 'Birinci kişi nereye oturursa otursun ikinci kişi kalan 9 sandalyeden birine düşer ve yalnız biri tam karşıdadır.'),
  ('Beş katlı bir binanın zemin katında asansöre binen üç kişinin her biri 1–5. katlardan birinde, birbirinden bağımsız ve eşit olasılıkla iniyor. Üçünün de farklı katlarda inme olasılığı kaçtır?', '12/25', ['24/125', '1/25', '2/5'], 'Farklı katlar için 5 × 4 × 3 = 60, toplam 5³ = 125 durum vardır: 60/125 = 12/25.'),
  ('Beş top, üç kutudan birine her top için bağımsız ve eşit olasılıkla atılıyor. Birinci kutunun boş kalma olasılığı kaçtır?', '32/243', ['211/243', '1/243', '80/243'], 'Her topun birinci kutuya gitmeme olasılığı 2/3\'tür: (2/3)⁵ = 32/243.'),
  ('Dört top dört kutuya, her top için bağımsız ve eşit olasılıkla yerleştiriliyor. Her kutuya tam bir top düşme olasılığı kaçtır?', '3/32', ['1/4', '1/24', '3/128'], 'Uygun yerleşimler 4! = 24, tüm yerleşimler 4⁴ = 256\'dır: 24/256 = 3/32.'),
  ('100 ile 999 arasındaki üç basamaklı sayılardan biri rastgele seçiliyor. Sayının rakamlarının birbirinden farklı olma olasılığı kaçtır?', '0,72', ['0,648', '0,81', '0,7'], 'Rakamları farklı sayılar 9 × 9 × 8 = 648 tanedir; 648/900 = 0,72.'),
  ('1\'den 10\'a kadar olan sayılardan farklı üç tanesi rastgele seçiliyor. Seçilenlerin en büyüğünün 7 olma olasılığı kaçtır?', '1/8', ['1/10', '3/10', '7/40'], '7 seçilmeli, diğer ikisi 1–6 arasından gelmelidir: C(6, 2)/C(10, 3) = 15/120 = 1/8.'),
  ('1\'den 10\'a kadar olan sayılardan farklı üç tanesi rastgele seçiliyor. Seçilen sayıların toplamının çift olma olasılığı kaçtır?', '1/2', ['1/3', '5/12', '7/12'], 'Toplam çift için üçü çift (C(5, 3) = 10) ya da ikisi tek biri çift (C(5, 2) × 5 = 50) olmalıdır: 60/120 = 1/2.'),
  ('Satranç tahtasının 64 karesinden farklı iki tanesi rastgele seçiliyor. İki karenin aynı satırda ya da aynı sütunda olma olasılığı kaçtır?', '2/9', ['14/64', '1/8', '7/9'], 'Birinci kareden sonra kalan 63 kareden 7\'si aynı satırda, 7\'si aynı sütundadır: 14/63 = 2/9.'),
  ('Bir satranç tahtası üzerine iki farklı kare rastgele işaretleniyor. Bu iki karenin aynı renge (ikisi de beyaz ya da ikisi de siyah) boyalı olma ihtimali nedir?', '31/63', ['1/2', '32/63', '33/64'], 'Birinci kareyle aynı renkte kalan 31 kare vardır ve toplam 63 kare kalmıştır: 31/63.'),
  ('Bir küpün sekiz köşesinden farklı iki tanesi rastgele seçiliyor. Bu iki köşenin küpün bir ayrıtıyla doğrudan bağlı olma olasılığı kaçtır?', '3/7', ['3/8', '12/56', '1/4'], 'Küpün 12 ayrıtı vardır ve köşe çifti sayısı C(8, 2) = 28\'dir: 12/28 = 3/7.'),
  ('Bir öğrenci okula üç yoldan birini 0,5, 0,3 ve 0,2 olasılıklarla seçiyor. Bu yollarda geç kalma olasılıkları sırasıyla 0,1, 0,2 ve 0,4\'tür. Öğrencinin geç kaldığı bir günde üçüncü yolu kullanmış olma olasılığı kaçtır?', '8/19', ['2/5', '10/19', '5/19'], 'Geç kalma olasılığı 0,05 + 0,06 + 0,08 = 0,19\'dur. Üçüncü yolun payı 0,08 olduğundan sonsal 8/19\'dur.'),
  ('Bir bölgedeki kuşların %10\'u A türündendir. A türü kuşların %80\'i, diğer kuşların %20\'si göçmendir. Rastgele yakalanan göçmen bir kuşun A türünden olma olasılığı kaçtır?', '4/13', ['4/5', '1/10', '8/13'], 'P(A ∩ göçmen) = 0,08; P(göçmen) = 0,08 + 0,9 × 0,2 = 0,26\'dır. 0,08 / 0,26 = 4/13 bulunur.'),
  ('Önsel olasılığı 0,5 olan bir H hipotezi için E kanıtı H doğruyken 0,2, H yanlışken 0,6 olasılıkla gözleniyor. E gözlendikten sonra H\'nin olasılığı kaçtır?', '0,25', ['0,5', '0,2', '0,333'], 'Sonsal = 0,5 × 0,2 / (0,5 × 0,2 + 0,5 × 0,6) = 0,1 / 0,4 = 0,25\'tir; kanıt H aleyhine olduğundan olasılık düşer.'),
  ('Bir risk grubunda hastalığın yaygınlığı %30\'dur. Duyarlılığı 0,9 ve özgüllüğü 0,95 olan bir testin bu gruptaki pozitif öngörü değeri yaklaşık kaçtır?', '0,89', ['0,30', '0,95', '0,2700'], 'Doğru pozitifler 0,3 × 0,9 = 0,27, yanlış pozitifler 0,7 × 0,05 = 0,035\'tir. 0,27 / 0,305 ≈ 0,89 bulunur; yaygınlık yüksek olduğunda pozitif sonuç daha güvenilirdir.'),
  ('Arama kuramında bir nesnenin bir bölgede bulunma olasılığı aranıp bulunamadıkça nasıl değişir?', 'Azalır, diğer bölgelerin olasılıkları artar', ['Artar, çünkü arama sürdükçe nesneye daha çok yaklaşılmaktadır', 'Değişmez, çünkü nesne yer değiştirmez', 'Sıfıra iner, diğer bölgeler değişmez'], 'Başarısız arama, o bölge için olumsuz kanıttır; Bayes güncellemesiyle o bölgenin olasılığı düşer ve kalan olasılık diğer bölgelere dağılır.'),
  ('28 taşlık standart bir domino takımından rastgele bir taş seçiliyor. Taşın üzerindeki noktaların toplamının 6 olma olasılığı kaçtır?', '1/7', ['1/4', '5/28', '1/6'], 'Toplamı 6 olan taşlar 0–6, 1–5, 2–4 ve 3–3 olmak üzere 4 tanedir: 4/28 = 1/7.'),
  ('Bağımsız üç olayın olasılıkları 0,5, 0,4 ve 0,2\'dir. Bu olaylardan tam olarak birinin gerçekleşme olasılığı kaçtır?', '0,46', ['0,24', '1,1', '0,375'], '0,5 × 0,6 × 0,8 + 0,5 × 0,4 × 0,8 + 0,5 × 0,6 × 0,2 = 0,24 + 0,16 + 0,06 = 0,46 bulunur.'),
  ('Bir öğrenci birbirinden bağımsız üç sınava giriyor; geçme olasılıkları 0,5, 0,4 ve 0,2\'dir. Öğrencinin en az iki sınavı geçme olasılığı kaçtır?', '0,30', ['0,26', '0,04', '0,465'], 'Tam iki sınav: 0,16 + 0,06 + 0,04 = 0,26; üçü birden: 0,04. Toplam 0,30\'dur.'),
  ('52\'lik desteden bir kart çekiliyor. Kartın kırmızı, as ya da figürlü kartlardan en az biri olma olasılığı kaçtır?', '17/26', ['8/13', '19/52', '9/13'], '26 kırmızı karta 2 siyah as ve 6 siyah figür eklenir: 34/52 = 17/26.'),
  ('1\'den 30\'a kadar olan tam sayılardan biri seçiliyor. Sayının 2 ya da 3 ile bölünüp 6 ile bölünmeme olasılığı kaçtır?', '1/2', ['2/3', '1/6', '7/15'], '2 ya da 3 ile bölünen 15 + 10 − 5 = 20 sayıdan 6\'nın katı olan 5 sayı çıkarılır: 15/30 = 1/2.'),
  ('Yüzlerinde 1, 1, 2, 2, 2 ve 3 yazan bir zar iki kez atılıyor. Gelen sayıların toplamının 4 olma olasılığı kaçtır?', '13/36', ['25/72', '1/3', '11/36'], 'P(1) = 1/3, P(2) = 1/2, P(3) = 1/6\'dır. Toplam 4 için (1, 3), (3, 1) ve (2, 2): 1/18 + 1/18 + 1/4 = 13/36.'),
  ('İki değişkenli bir sıklık tablosunda her hücre kendi satır toplamına bölünürse elde edilen oranlar neyi verir?', 'Satır değişkeni verildiğinde sütun değişkeninin koşullu olasılıklarını', ['Satır ve sütunun birleşik olasılıklarını, yani kesişim oranlarını', 'Sütun değişkeninin marjinal olasılıklarını', 'Sütun verildiğinde satır değişkeninin koşullu olasılıklarını'], 'Satır toplamına bölmek, örnek uzayı o satırla sınırlar; bu da satır kategorisi verildiğindeki koşullu dağılımdır.'),
  ('Bir çalışmada 120 hasta ilaç, 80 hasta plasebo almıştır. İlaç alanların 90\'ı, plasebo alanların 40\'ı iyileşmiştir. İyileşen hastalardan rastgele birinin ilaç almış olma olasılığı kaçtır?', '9/13', ['3/4', '9/20', '13/20'], 'Toplam 130 iyileşen hastanın 90\'ı ilaç grubundadır: 90/130 = 9/13.'),
  ('Çok büyük bir topluluktan yerine koymadan küçük bir örneklem seçilirken çekilişlerin yaklaşık bağımsız kabul edilebilmesinin nedeni nedir?', 'Bir kişinin çıkarılması kalan oranları neredeyse değiştirmez', ['Yerine koymadan çekilişler her zaman bağımsızdır', 'Büyük topluluklarda olasılıklar 1/2\'ye eşitlenir', 'Örneklemdeki herkes aynı özelliğe sahiptir'], 'Örneğin 1.000.000 kişiden birinin çıkması kalan oranı ancak milyonda bir düzeyinde değiştirir; koşullu olasılıklar koşulsuz olanlara çok yakındır.'),
  ('Bir fırında ekmeklerin %20\'si tam buğdaydır; tam buğdayların %40\'ı, diğerlerinin %10\'u dilimlenmiştir. Dilimlenmiş bir ekmeğin tam buğday olma olasılığı kaçtır?', '1/2', ['2/5', '1/5', '4/25'], 'Dilimlenmiş ekmeklerin 0,08\'i tam buğday, 0,08\'i diğerlerindendir; ikisi eşit olduğundan olasılık 1/2\'dir.'),
  ('Bir basketbolcu ilk serbest atışı 0,7 olasılıkla sokuyor; ilki girerse ikinciyi 0,8, girmezse 0,6 olasılıkla sokuyor. İkinci atışın girme olasılığı kaçtır?', '0,74', ['0,70', '0,56', '0,625'], 'Toplam olasılık: 0,7 × 0,8 + 0,3 × 0,6 = 0,56 + 0,18 = 0,74.'),
  ('Bir hayvan barınağındaki hayvanların %70\'i köpek, %30\'u kedidir. Köpeklerin %60\'ı, kedilerin %30\'u aşılıdır. Rastgele seçilen aşılı bir hayvanın kedi olma olasılığı kaçtır?', '3/17', ['3/10', '9/100', '14/17'], 'P(kedi ∩ aşılı) = 0,09; P(aşılı) = 0,42 + 0,09 = 0,51\'dir. 0,09 / 0,51 = 3/17 bulunur.'),
  ('100 biletin satıldığı bir çekilişte 3 farklı bilete ödül veriliyor. 5 bilet alan birinin en az bir ödül kazanma olasılığı yaklaşık kaçtır?', '0,144', ['0,15', '0,05', '0,1584'], 'Hiç ödül kazanmama olasılığı C(95, 3)/C(100, 3) ≈ 0,856\'dır; tümleyeni yaklaşık 0,144\'tür.'),
  ('Üç kapıdan biri rastgele seçiliyor; kapıların ardında sırasıyla 0,9, 0,5 ve 0,1 olasılıkla canavar bulunuyor. Oyuncu canavarla karşılaştıysa birinci kapıyı seçmiş olma olasılığı kaçtır?', '0,6', ['0,9', '0,3', '0,333'], 'Sonsal (1/3)(0,9) / 0,5 = 0,3 / 0,5 = 0,6 olur.'),
  ('Bir kafede müşterilerin %35\'i tatlı sipariş ediyor. Tatlı sipariş edenlerin %80\'i, etmeyenlerin %40\'ı kahve de alıyor. Kahve alan bir müşterinin tatlı da sipariş etmiş olma olasılığı kaçtır?', '0,52', ['0,35', '0,28', '0,625'], 'P(tatlı ∩ kahve) = 0,28; P(kahve) = 0,28 + 0,65 × 0,4 = 0,54\'tür. 0,28 / 0,54 ≈ 0,52 bulunur.'),
  ('Bir paketteki tohumların %60\'ı kırmızı, %40\'ı beyaz çiçekli bitki verir; kırmızıların %90\'ı, beyazların %80\'i çimlenir. Çimlenen bir tohumun beyaz çiçek açma olasılığı yaklaşık kaçtır?', '0,37', ['0,40', '0,32', '0,4651'], 'P(beyaz ∩ çimlenme) = 0,32, P(çimlenme) = 0,86\'dır. 0,32 / 0,86 ≈ 0,37 bulunur.'),
  ('Miladi takvimde 400 yıllık bir döngüde 97 artık yıl bulunur. Bu döngüden rastgele seçilen bir yılın artık yıl olma olasılığı kaçtır?', '97/400', ['1/4', '3/400', '103/400'], 'Dörde bölünen 100 yıldan 100\'e bölünüp 400\'e bölünmeyen 3 yıl çıkarılır: 97/400.'),
  ('Bir zar çifti atıldığında gelen iki sayı çarpılıyor. Elde edilen çarpımın 1, 4, 9, 16, 25 ya da 36 gibi bir tam kare olması hangi olasılıkla gerçekleşir?', '2/9', ['1/6', '1/4', '7/36'], 'Çiftler (1,1), …, (6,6) olmak üzere 6 sonuç ile (1,4) ve (4,1) çarpımı tam kare yapar: 8/36 = 2/9.'),
  ('Bir laboratuvar beş kişinin kan örneklerini karıştırıp tek test yapıyor. Her kişinin bağımsız olarak pozitif olma olasılığı 0,02\'dir. Karışık örneğin negatif çıkma (kimsenin pozitif olmama) olasılığı yaklaşık kaçtır?', '0,90', ['0,98', '0,10', '0,8154'], 'Beş kişinin hepsinin negatif olması gerekir: 0,98⁵ ≈ 0,904.'),
  ('Birler basamağı 7 olan iki basamaklı sayılardan biri rastgele seçiliyor. Sayının asal olma olasılığı kaçtır?', '5/9', ['4/9', '11/18', '2/3'], '17, 27, …, 97 arasındaki 9 sayıdan 17, 37, 47, 67 ve 97 asaldır; 27, 57, 77 ve 87 asal değildir.'),
  ('Bir torbada 2 beyaz ve 1 siyah top var. İki oyuncu sırayla ve yerine koyarak birer top çekiyor; siyahı ilk çeken kazanıyor. Oyuna başlayan oyuncunun kazanma olasılığı kaçtır?', '3/5', ['1/3', '5/12', '2/3'], '(1/3) / (1 − (2/3)²) = (1/3) / (5/9) = 3/5 bulunur.'),
  ('P(B) > 0 olmak üzere aşağıdaki eşitsizliklerden hangisi her zaman doğrudur?', 'P(A ∩ B) ≤ P(A|B)', ['P(A|B) ≤ P(A), çünkü koşul olasılığı küçültür', 'P(A|B) ≤ P(A ∩ B)', 'P(A) ≤ P(A|B)'], 'P(A ∩ B) = P(A|B)·P(B) ve P(B) ≤ 1 olduğundan kesişimin olasılığı koşullu olasılığı aşamaz.'),
  ('P(A|B) = 0,3 olduğu biliniyor (0 < P(B) < 1). P(A|B\') için hangisi doğrudur?', 'Bu bilgiden belirlenemez; 0 ile 1 arasında herhangi bir değer olabilir', ['0,7 olmak zorundadır', '0,3 olmak zorundadır', '0,3\'ten büyük olmak zorundadır, çünkü tümleyen koşul daha geniştir ve olasılığı da daha büyük olur'], 'P(A|B) ile P(A|B\') farklı koşullardaki olasılıklardır; toplamları 1 olmak zorunda değildir. 1 olan toplam P(A|B) + P(A\'|B)\'dir.'),
  ('Bir dondurmacıda müşterilerin %60\'ı külah, %40\'ı kâse alıyor; külahçıların %50\'si, kâsecilerin %75\'i çikolatalı seçiyor. Çikolatalı dondurma alan bir müşterinin külah almış olma olasılığı kaçtır?', '1/2', ['3/5', '3/10', '1/4'], 'P(külah ∩ çikolata) = 0,3 ve P(çikolata) = 0,6\'dır: 0,3 / 0,6 = 1/2.'),
  ('1000 kişilik bir taramada 50 kişi hastadır. Test hastaların 45\'ini, sağlıklı 950 kişinin 95\'ini pozitif buluyor. Testi pozitif çıkan birinin gerçekten hasta olma olasılığı kaçtır?', '9/28', ['9/10', '9/19', '45/1000'], 'Pozitif sonuçlar 45 + 95 = 140 kişidir ve bunların 45\'i hastadır: 45/140 = 9/28.'),
  ('Bir test hastalarda %80 pozitif, sağlıklılarda %10 pozitif sonuç veriyor. Hastalığın yaygınlığı %50 olan bir grupta testi pozitif çıkan birinin hasta olma olasılığı kaçtır?', '8/9', ['0,8', '0,45', '0,9'], 'Doğru pozitifler 0,40, yanlış pozitifler 0,05\'tir: 0,40 / 0,45 = 8/9.'),
  ('Bir testin duyarlılığı artırılıp özgüllüğü aynı tutulursa, diğer koşullar değişmeden negatif öngörü değeri nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Sıfır olur'], 'Duyarlılık arttıkça hastalarda negatif sonuç azalır; negatif çıkanlar arasında hasta oranı düşer ve negatif sonuç daha güvenilir olur.'),
  ('Bir hastalık için duyarlılığı %100 olan bir testin negatif çıkması ne anlama gelir?', 'Kişi kesinlikle hasta değildir', ['Kişi kesinlikle hastadır', 'Kişinin hasta olma olasılığı yaygınlığa eşittir', 'Test yeniden yapılmadan hiçbir şey söylenemez'], 'Duyarlılık %100 ise bütün hastaların testi pozitif çıkar; negatif sonuç yalnız sağlıklılarda görülür.'),
  ('Bir hastalık için özgüllüğü %100 olan bir testin pozitif çıkması ne anlama gelir?', 'Kişi kesinlikle hastadır', ['Kişi kesinlikle hasta değildir', 'Pozitif öngörü değeri duyarlılığa eşittir', 'Kişinin hasta olma olasılığı %50\'dir'], 'Özgüllük %100 ise hiçbir sağlıklı kişide pozitif sonuç çıkmaz; pozitif sonuç yalnız hastalarda görülür.'),
  ('1\'den 5\'e kadar numaralı toplardan ikisi yerine koymadan çekiliyor ve numaraların toplamının çift olduğu biliniyor. İki numaranın da tek olma olasılığı kaçtır?', '3/4', ['3/10', '1/2', '3/5'], 'Toplamı çift olan çiftler: iki tek C(3, 2) = 3, iki çift C(2, 2) = 1. Koşullu olasılık 3/4\'tür.'),
  ('Bir kentte seçmenlerin %60\'ı A adayını destekliyor. A destekçilerinin %80\'i, diğer seçmenlerin %50\'si oy kullanıyor. Oy kullananlar arasında A destekçilerinin oranı yaklaşık kaçtır?', '0,71', ['0,60', '0,48', '0,625'], 'P(A ∩ oy) = 0,48, P(oy) = 0,48 + 0,4 × 0,5 = 0,68\'dir. 0,48 / 0,68 ≈ 0,71 bulunur.'),
  ('Bir para atılıyor; yazı gelirse bir zar bir kez, tura gelirse aynı zar iki kez atılıyor. Zar atışlarında en az bir 6 görülme olasılığı kaçtır?', '17/72', ['1/6', '11/36', '35/72'], '(1/2)(1/6) + (1/2)(11/36) = 6/72 + 11/72 = 17/72 bulunur.'),
  ('Bir tenisçinin ilk servisi 0,6 olasılıkla içeri giriyor ve bu durumda sayıyı 0,7 olasılıkla kazanıyor. İlk servis dışarı giderse ikinci servis 0,9 olasılıkla içeri giriyor ve sayı 0,5 olasılıkla kazanılıyor; ikinci servis de dışarıysa sayı kaybediliyor. Sayıyı kazanma olasılığı kaçtır?', '0,60', ['0,42', '0,65', '0,575'], '0,6 × 0,7 + 0,4 × 0,9 × 0,5 = 0,42 + 0,18 = 0,60 bulunur.'),
  ('Bir şirkete başvuranların %30\'u deneyimlidir. Deneyimlilerin %50\'si, deneyimsizlerin %20\'si işe alınıyor. İşe alınan birinin deneyimli olma olasılığı yaklaşık kaçtır?', '0,52', ['0,30', '0,15', '0,7143'], 'P(deneyimli ∩ alındı) = 0,15, P(alındı) = 0,15 + 0,14 = 0,29\'dur. 0,15 / 0,29 ≈ 0,52 bulunur.'),
  ('A torbasında 3 kırmızı 2 beyaz, B torbasında 2 kırmızı 3 beyaz top vardır. Zar 1 ya da 2 gelirse A\'dan, aksi hâlde B\'den bir top çekiliyor. Çekilen top beyaz ise A torbasından gelmiş olma olasılığı kaçtır?', '1/4', ['4/15', '2/5', '3/8'], 'P(A ∩ beyaz) = (1/3)(2/5) = 2/15, P(B ∩ beyaz) = (2/3)(3/5) = 6/15\'tir. 2/15 ÷ 8/15 = 1/4.'),
  ('Bir oyunda üç para atışının sonucu gizli tutuluyor; sunucu yalnızca "yazıların sayısı ikiden az değil" diyor. Birinci paranın yazı göstermesi hangi olasılıkla doğrudur?', '3/4', ['11/16', '2/3', '7/8'], 'Koşulu sağlayan diziler YYT, YTY, TYY ve YYY\'dir; bunların 3\'ü yazıyla başlar.'),
  ('Hilesiz bir para dört kez atılıyor ve tam iki yazı geldiği biliniyor. İki yazının art arda iki atışta gelmiş olma olasılığı kaçtır?', '1/2', ['5/16', '3/8', '2/3'], 'İki yazının konumları C(4, 2) = 6 eşit olası biçimde seçilir; komşu konum çiftleri (1,2), (2,3), (3,4) olmak üzere 3 tanedir.'),
  ('Üç zar atılıyor ve toplamın 5 olduğu biliniyor. Zarlardan birinin 3 gösterme olasılığı kaçtır?', '1/2', ['1/3', '5/12', '2/3'], 'Toplamı 5 yapan sıralı sonuçlar (1,1,3)\'ün 3 ve (1,2,2)\'nin 3 dizilişidir; 6 sonucun 3\'ünde bir 3 vardır.'),
  ('İki zar atılıyor ve büyük olan zarın 5 olduğu biliniyor. Toplamın 10 olma olasılığı kaçtır?', '1/9', ['1/11', '1/6', '2/9'], 'En büyüğü 5 olan 25 − 16 = 9 sonuç vardır; yalnız (5, 5) toplamı 10 yapar.'),
  ('10 ampulün 3\'ü bozuktur. Rastgele 2 ampul alınıyor ve en az birinin bozuk olduğu biliniyor. İkisinin de bozuk olma olasılığı kaçtır?', '1/8', ['1/15', '3/10', '1/3'], 'P(ikisi bozuk) = 3/45, P(en az biri bozuk) = 1 − 21/45 = 24/45\'tir. 3/24 = 1/8 bulunur.'),
  ('Bir kursta öğrencilerin %20\'si ileri, %50\'si orta, %30\'u başlangıç düzeyindedir ve geçme olasılıkları 0,9, 0,6 ve 0,3\'tür. Sınavı geçen bir öğrencinin başlangıç düzeyinde olma olasılığı kaçtır?', '3/19', ['0,333', '0,09', '6/19'], 'P(başlangıç ∩ geçti) = 0,09, P(geçti) = 0,57\'dir: 0,09 / 0,57 = 3/19.'),
  ('52\'lik bir deste karılıp kartlar tek tek açılıyor. İlk asın tam olarak ikinci açılan kart olma olasılığı yaklaşık kaçtır?', '0,072', ['0,077', '0,0059', '0,1448'], 'İlk kart as olmamalı, ikinci kart as olmalıdır: (48/52)(4/51) = 16/221 ≈ 0,072.'),
  ('Dört kişinin getirdiği hediyeler karıştırılıp rastgele dağıtılıyor. Ali ile Ayşe\'nin ikisinin de kendi getirdiği hediyeyi geri alma olasılığı kaçtır?', '1/12', ['3/24', '1/24', '1/6'], 'Bu iki kişi sabitlendikten sonra kalan iki hediye 2! biçimde dağılır: 2/4! = 2/24 = 1/12.'),
  ('Günlerin %10\'unun sisli olduğu bir kentte vapur seferleri sisli günlerde 0,6, diğer günlerde 0,02 olasılıkla iptal ediliyor. Seferlerin iptal edildiği bir günün sisli olma olasılığı yaklaşık kaçtır?', '0,77', ['0,10', '0,60', '0,6923'], 'P(sis ∩ iptal) = 0,06, P(iptal) = 0,078\'dir: 0,06 / 0,078 ≈ 0,77.'),
  ('Türk alfabesinin 29 harfinden farklı iki tanesi rastgele seçiliyor. İki harfin de ünlü olma olasılığı kaçtır?', '2/29', ['64/841', '8/29', '1/14'], 'C(8, 2)/C(29, 2) = 28/406 = 2/29 bulunur.'),
  ('Üç garsonun eşit sıklıkta sipariş aldığı bir kafede yanlış getirme olasılıkları 0,05, 0,10 ve 0,15\'tir. Yanlış gelen bir siparişi üçüncü garsonun getirmiş olma olasılığı kaçtır?', '1/2', ['1/3', '0,15', '1/6'], 'Yanlış siparişlerin payları 0,05 : 0,10 : 0,15 yani 1 : 2 : 3 oranındadır; üçüncünün payı 3/6 = 1/2\'dir.'),
  ('Bir hastanede bebeklerin %2\'si erken doğuyor. Erken doğan bebeklerin %50\'si, zamanında doğanların %1\'i yoğun bakıma alınıyor. Yoğun bakımdaki bir bebeğin erken doğmuş olma olasılığı yaklaşık kaçtır?', '0,51', ['0,50', '0,02', '0,0198'], 'P(erken ∩ yoğun bakım) = 0,01, P(yoğun bakım) = 0,01 + 0,98 × 0,01 = 0,0198\'dir. 0,01 / 0,0198 ≈ 0,51.'),
  ('52\'lik desteden iki kart çekiliyor. İki kartın da kırmızı figürlü (kupa ya da karo vale, kız, papaz) olma olasılığı kaçtır?', '5/442', ['9/676', '1/221', '3/26'], 'Altı kırmızı figürden iki kart C(6, 2) = 15 biçimde seçilir: 15/1326 = 5/442.'),
  ('Bir gece bir tilkinin kameralı tuzağın önünden geçme olasılığı 0,3\'tür. Tilki geçerse kamera 0,8 olasılıkla kayıt yapıyor ve tilki dışında kayıt tetiklenmiyor. Sabah kayıt bulunmadığına göre tilkinin yine de geçmiş olma olasılığı yaklaşık kaçtır?', '0,08', ['0,30', '0,06', '0,125'], 'P(geçti ∩ kayıt yok) = 0,3 × 0,2 = 0,06, P(kayıt yok) = 0,06 + 0,7 = 0,76\'dır: 0,06 / 0,76 ≈ 0,08.'),
  ('Bir hipotezin önsel bahis oranı 1\'e 4\'tür. Gözlenen kanıtın olabilirlik oranı 8 ise hipotezin sonsal olasılığı kaçtır?', '2/3', ['8/13', '8/9', '4/5'], 'Sonsal oran (1/4) × 8 = 2, yani 2\'ye 1\'dir. Olasılığa çevrilince 2/(2 + 1) = 2/3 bulunur.'),
  ('Bir olayın önsel olasılığı 0,2\'dir. Olabilirlik oranı 4 olan bir kanıt gözleniyor. Sonsal olasılık kaçtır?', '1/2', ['0,8', '0,24', '0,6'], 'Önsel oran 0,2/0,8 = 1/4\'tür. 4 ile çarpılınca 1 olur; olasılık 1/(1 + 1) = 1/2 bulunur.'),
  ('Hilesiz bir zar atılıyor; gelen sayı çift ise bir para, tek ise iki para atılıyor. En az bir yazı gelme olasılığı kaçtır?', '5/8', ['3/4', '11/16', '7/8'], '(1/2)(1/2) + (1/2)(3/4) = 1/4 + 3/8 = 5/8 bulunur.'),
  ('Bir şirket çalışanlarının %30\'u uzaktan çalışıyor. Uzaktan çalışanların %20\'si, ofiste çalışanların %10\'u bir ay içinde işten ayrılıyor. İşten ayrılan bir çalışanın uzaktan çalışan olma olasılığı kaçtır?', '6/13', ['0,0613', '0,06', '7/13'], 'P(uzak ∩ ayrılma) = 0,06, P(ayrılma) = 0,06 + 0,07 = 0,13\'tür: 0,06/0,13 = 6/13.'),
  ('Kenarı 1 olan bir karenin içinden rastgele bir (x, y) noktası seçiliyor ve x > y olduğu biliniyor. Noktanın x > 1/2 koşulunu da sağlama olasılığı kaçtır?', '3/4', ['11/16', '3/8', '2/3'], 'x > y bölgesinin alanı 1/2\'dir. Bunun x > 1/2 olan kısmının alanı ∫ x dx (1/2\'den 1\'e) = 3/8\'dir. Oran (3/8)/(1/2) = 3/4.'),
  ('Yarıçapı 1 olan bir dairenin içinden rastgele bir nokta seçiliyor ve noktanın merkeze uzaklığının 3/4\'ten küçük olduğu biliniyor. Uzaklığın 1/2\'den de küçük olma olasılığı kaçtır?', '4/9', ['2/3', '1/4', '9/16'], 'Alanlar yarıçapın karesiyle orantılıdır: (1/2)² / (3/4)² = (1/4)/(9/16) = 4/9.'),
  ('Üç zar atılıyor ve en az bir zarın 6 geldiği biliniyor. Tam olarak bir zarın 6 gelmiş olma olasılığı kaçtır?', '75/91', ['91/216', '25/72', '90/91'], 'P(tam bir 6) = 3 × 25/216 = 75/216, P(en az bir 6) = 91/216\'dır. Oran 75/91 bulunur.'),
  ('52\'lik desteden üç kart çekiliyor ve üçünün de kupa olduğu görülüyor. Bu kartlar arasında kupa ası bulunma olasılığı kaçtır?', '3/13', ['1/13', '3/52', '39/52'], 'Kupa ası bulunmama olasılığı C(12, 3)/C(13, 3) = 220/286\'dır; tümleyeni 66/286 = 3/13\'tür. Kısaca her kupa kartının seçilme olasılığı 3/13\'tür.'),
  ('52\'lik desteden dört oyuncuya birer kart dağıtılıyor. Hiçbir oyuncuya as gelmeme olasılığı yaklaşık kaçtır?', '0,72', ['0,69', '0,92', '0,0819'], 'Dört kartın da as olmayan 48 karttan gelmesi gerekir: C(48, 4)/C(52, 4) ≈ 0,719.'),
  ('Bir evde bir günde yangın çıkma olasılığı 0,001\'dir. Duman dedektörü yangında 0,95 olasılıkla, yangın yokken 0,002 olasılıkla alarm veriyor. Alarm çaldığında gerçekten yangın olma olasılığı yaklaşık kaçtır?', '0,32', ['0,95', '0,50', '0,0475'], 'P(yangın ∩ alarm) = 0,00095, P(alarm) = 0,00095 + 0,999 × 0,002 ≈ 0,00295\'tir. Oran yaklaşık 0,32\'dir.'),
  ('Bir şirket yöneticisi elindeki verilere göre iki olay için şu bilgileri veriyor: A olayının olasılığı 0,2; B gerçekleştiğinde A\'nın olasılığı 0,5; A gerçekleştiğinde B\'nin olasılığı 0,25. Bu durumda B olayının olasılığı nedir?', '0,1', ['0,25', '0,05', '0,4'], 'P(A ∩ B) = P(A)·P(B|A) = 0,05\'tir. P(B) = P(A ∩ B)/P(A|B) = 0,05/0,5 = 0,1 bulunur.'),
  ('Bir anket grubunun %40\'ı kitap okuyor, %25\'i hem kitap okuyor hem de tiyatroya gidiyor, %50\'si tiyatroya gidiyor. Kitap okuyan bir kişinin tiyatroya gitmeme olasılığı kaçtır?', '0,375', ['0,625', '0,15', '0,1250'], 'P(tiyatro | kitap) = 0,25/0,40 = 0,625\'tir; aynı koşul altında tümleyeni 0,375\'tir.'),
  ('Bir anahtar kutusundaki 4 anahtardan 2\'si kapıyı açıyor. Anahtarlar rastgele ve denenen ayrılarak sırayla deneniyor. Kapının ilk denemede açılmayıp ikinci denemede açılma olasılığı kaçtır?', '1/3', ['5/12', '1/2', '2/3'], 'İlk anahtarın açmama olasılığı 2/4, ardından ikincinin açma olasılığı 2/3\'tür: (1/2)(2/3) = 1/3.'),
  ('Bir dizi bağımsız atışta başarı olasılığı 0,3\'tür. İlk iki atış başarısız geçtiğine göre ilk başarının üçüncü atışta gelme olasılığı kaçtır?', '0,3', ['0,147', '0,09', '0,49'], 'Atışlar bağımsız olduğundan geçmiş başarısızlıklar bilindiğinde üçüncü atışın başarı olasılığı yine 0,3\'tür.'),
  ('Bir çekmecede iki madeni para duruyor: biri normal, diğerinin iki yüzünde de yazı basılı. Bakmadan alınan para iki kez havaya atılıyor ve iki atışta da yazı görülüyor. Elinizdeki paranın iki yüzü yazı olan para olma ihtimali nedir?', '4/5', ['2/3', '3/4', '11/15'], 'Olabilirlikler 1 ve 1/4\'tür; eşit önsellerle 1/(1 + 1/4) = 4/5 bulunur.'),
  ('İki olay için P(A ∩ B) = 0,2, P(A ∩ B\') = 0,3 ve P(A\' ∩ B) = 0,1\'dir. B gerçekleştiğinde A\'nın gerçekleşme olasılığı kaçtır?', '2/3', ['0,4444', '1/2', '0,2'], 'P(B) = 0,2 + 0,1 = 0,3\'tür. P(A|B) = 0,2/0,3 = 2/3 bulunur.'),
  ('Yazı gelme olasılığı 0,7 olan hileli bir para iki kez atılıyor ve iki sonucun aynı olduğu biliniyor. İkisinin de yazı olma olasılığı yaklaşık kaçtır?', '0,84', ['0,70', '0,49', '0,625'], 'P(YY) = 0,49, P(aynı) = 0,58\'dir. 0,49 / 0,58 ≈ 0,84 bulunur.'),
  ('Bir sınıfın yarısı erkektir. Erkeklerin %10\'u, kızların %20\'si solaktır. Rastgele seçilen solak bir öğrencinin kız olma olasılığı kaçtır?', '2/3', ['1/2', '4/15', '3/4'], 'P(kız ∩ solak) = 0,10, P(solak) = 0,05 + 0,10 = 0,15\'tir: 0,10/0,15 = 2/3.'),
  ('İki özellik bakımından AaBb genotipli bir birey, aabb genotipli bir bireyle çaprazlanıyor; genler bağımsız kalıtılıyor. Yavrunun Aabb genotipinde olma olasılığı kaçtır?', '1/4', ['1/16', '1/2', '1/8'], 'Aa olma olasılığı 1/2, bb olma olasılığı 1/2\'dir: (1/2)(1/2) = 1/4.'),
  ('Doğum günleri 365 güne eşit dağılmışsa 3 kişilik bir grupta en az iki kişinin aynı gün doğmuş olma olasılığı yaklaşık kaçtır?', '0,008', ['0,003', '0,0027', '0,08'], 'Hepsinin farklı olma olasılığı (364/365)(363/365) ≈ 0,9918\'dir; tümleyeni yaklaşık 0,008\'dir.'),
  ('Sınıf başkanlığı oylamasında Deniz 5, Ece 3 oy almış; kâğıtlar karıştırılıp birer birer okunuyor. Okuma süresince Deniz\'in oy sayısının Ece\'ninkinden hep fazla kalması hangi olasılıkla gerçekleşir?', '1/4', ['5/8', '1/8', '3/8'], 'Oy pusulası teoremine göre olasılık (a − b)/(a + b) = (5 − 3)/8 = 1/4\'tür.'),
  ('52\'lik desteden iki kart çekiliyor. İki kartın aynı renkte (ikisi kırmızı ya da ikisi siyah) olma olasılığı kaçtır?', '25/51', ['1/2', '26/51', '51/104'], 'İlk kart ne olursa olsun kalan 51 kartın 25\'i onunla aynı renktedir.'),
  ('52\'lik desteden iki kart çekiliyor. Kartlardan birinin kupa, diğerinin maça olma olasılığı kaçtır?', '13/102', ['1/16', '26/51', '13/204'], 'Sıralı iki durum vardır: 2 × (13/52)(13/51) = 338/2652 = 13/102.'),
  ('Bir torbada 3 kırmızı ve 1 mavi top var. Yerine koymadan iki top çekiliyor ve en az birinin kırmızı olduğu söyleniyor. İki topun da kırmızı olma olasılığı kaçtır?', '1/2', ['3/5', '9/16', '2/3'], 'Torbada tek mavi top olduğundan çekilen iki toptan en az biri her zaman kırmızıdır; koşul bilgi vermez. P(ikisi kırmızı) = C(3, 2)/C(4, 2) = 1/2.'),
  ('Bir sigorta şirketinin sürücülerinin %20\'si yüksek riskli (yıllık kaza olasılığı 0,3), %80\'i düşük risklidir (0,05). Bir yıl içinde kaza yapan bir sürücünün yüksek riskli olma olasılığı kaçtır?', '0,6', ['0,2', '0,3', '0,75'], 'P(yüksek ∩ kaza) = 0,06, P(kaza) = 0,06 + 0,04 = 0,10\'dur: 0,06 / 0,10 = 0,6.'),
  ('A ve B bağımsız olaylardır; P(A) = 0,3 ve P(B) = 0,5\'tir. Olaylardan en az birinin gerçekleştiği bilindiğinde A\'nın gerçekleşmiş olma olasılığı kaçtır?', '6/13', ['0,0975', '3/8', '0,65'], 'P(A ∪ B) = 0,3 + 0,5 − 0,15 = 0,65\'tir. A ⊂ A ∪ B olduğundan P(A | A ∪ B) = 0,3/0,65 = 6/13.'),
  ('Bir öğrencinin matematik ödevini bitirme olasılığı 0,8, fizik ödevini bitirme olasılığı 0,7\'dir ve ikisini birlikte bitirme olasılığı 0,6\'dır. Matematik ödevini bitirdiği bilinen öğrencinin fizik ödevini bitirmemiş olma olasılığı kaçtır?', '0,25', ['0,125', '0,2', '0,75'], 'P(fizik | matematik) = 0,6/0,8 = 0,75\'tir; aynı koşul altındaki tümleyeni 0,25\'tir.'),
  ('Bir sınavda 4 seçenekli soruların her birine rastgele yanıt veren bir öğrencinin ilk doğru yanıtını üçüncü soruda vermesi olasılığı kaçtır?', '9/64', ['1/4', '27/64', '3/64'], 'İlk iki soru yanlış, üçüncü soru doğru olmalıdır: (3/4)(3/4)(1/4) = 9/64.'),
  ('Bir kutuda 2 kırmızı ve 3 mavi top vardır. Toplar yerine konmadan tek tek çekiliyor. İki kırmızı topun ardışık iki çekilişte gelme olasılığı kaçtır?', '2/5', ['1/10', '1/5', '3/10'], 'Kırmızıların konumları C(5, 2) = 10 eşit olası biçimde seçilir; komşu konum çiftleri 4 tanedir: 4/10 = 2/5.'),
];
